// A refined variant of RAID_BOSSES (./data.ts) that is not used yet, kept here so ./data.ts
// remains untouched as a fallback. Built by merging ./data.ts with
// ../raid-bosses-import/raid-boss-details.ts (RAID_BOSS_DETAILS, fetched from
// https://lu4-wiki.hatemosphe.re/api/npc/{id}) and ./missing.ts (MISSING_RAID_BOSSES):
//
// - level, drops and worldX/worldY were replaced with RAID_BOSS_DETAILS's values for every
//   boss id present there (146 of 153). RAID_BOSS_DETAILS's drops are the complete list —
//   see ../raid-bosses-import/drop-count-comparison.ts: ./data.ts's drops were capped at the
//   top 20 by chance (a limit of the giran.info page ./data.ts was originally scraped from)
//   for 96 of those 146.
// - Drop item names: RAID_BOSS_DETAILS often omits the `Unidentified `/`Sealed ` prefix
//   ./data.ts uses for the same item (same itemId/icon, same chance) — 189 drop rows (90
//   distinct name pairs) were renamed back to ./data.ts's naming, matched per boss by trying
//   every combination of those two prefixes, not just the longest. (An earlier pass tried only
//   the longest matching prefix and wrongly concluded 32 items were entirely absent from the
//   wiki source — they were not; every one of them resolved once all prefix combinations were
//   tried.)
// - mapX/mapY were left as-is from ./data.ts everywhere they already existed; RAID_BOSS_DETAILS
//   has no map-pixel coordinate, only the world coordinate now used for worldX/worldY. Nothing
//   in the app reads mapX/mapY or worldX/worldY yet (verified — the map feature is unbuilt).
// - The 7 ids with no RAID_BOSS_DETAILS match (Core, Orfen, Queen Ant, and the 4 elemental
//   spirits — the API lists these under a different title: Epic Boss / Queen of Underground /
//   Subclass Raid Boss) kept their ./data.ts level/drops, but worldX/worldY were since updated
//   by hand to the same spawns-based coordinate as the other 146.
// - The 5 bosses from MISSING_RAID_BOSSES (./missing.ts) — present in RAID_BOSS_DETAILS but
//   never in ./data.ts — are appended as-is; they already went through the same
//   RAID_BOSS_DETAILS-derived shape when ./missing.ts was built. Their mapX/mapY (originally a
//   TODO placeholder, since the source had no map-pixel coordinate for them either) are now
//   computed: with all 153 other bosses' real mapX/mapY and spawns-based worldX/worldY as data
//   points, mapX = 1.329794 * worldX - 1248.6875 and mapY = 1.329795 * worldY - 35.9117 fits
//   with R² = 1.000000 (cross-validated by fitting the 7 vs. the other 146 independently and
//   predicting one set from the other, max error 0.08) — so these 5 use that formula rather
//   than a placeholder.
// - Any drop item icon this pulled in that wasn't downloaded to ./images/item-icons/ yet has
//   since been fetched and converted; none are missing as of this file's last update.
// - 4 bosses' location name/slug were repaired using the same mapping
//   apps/backend/src/helpers/catalog-source.ts applies to ./data.ts at read time
//   (COLLAPSED_LOCATIONS): the scraper had flattened two different Russian-named locations to
//   the placeholder slug 'x'. Applied directly here instead of at read time, since this file is
//   meant to be the corrected replacement; the runtime fix stays in catalog-source.ts as a
//   fallback for ./data.ts.
// - WORLD_MAP_IMAGE and DUNGEON_PLANS are copied verbatim from ./data.ts — untouched by any of
//   the above, so there is nothing to merge.
//
// Sorted by (level, name) ascending, same convention as ./data.ts.

